glsl:
vec2 rot2(vec2 v, float a) { float c=cos(a), s=sin(a); return vec2(v.x*c-v.y*s, v.x*s+v.y*c); }
vec3 rotY(vec3 v, float a) { float c=cos(a), s=sin(a); return vec3(v.x*c+v.z*s, v.y, -v.x*s+v.z*c); }
float hash(vec2 p) { return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
float noise(vec2 p) { vec2 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f); return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y); }
float fbm(vec2 p, int o) { float v=0.0,a=0.5; for(int i=0;i<5;i++){ if(i>=o)break; v+=a*noise(p); p*=2.02; a*=0.5; } return v; }
float sdBox(vec2 p, vec2 b) { vec2 d=abs(p)-b; return length(max(d,0.0))+min(max(d.x,d.y),0.0); }
float sdTwistedStrip(vec3 p, float R, float w, float h, float twist) {
    float ang=atan(p.z,p.x); vec2 q=vec2(length(p.xz)-R, p.y);
    q=rot2(q, ang*0.5+twist); return sdBox(q, vec2(w,h));
}
vec3 getNormal(vec3 p, float R, float w, float h, float twist) {
    float e=0.001; float d=sdTwistedStrip(p,R,w,h,twist);
    return normalize(vec3(
        sdTwistedStrip(p+vec3(e,0,0),R,w,h,twist)-d,
        sdTwistedStrip(p+vec3(0,e,0),R,w,h,twist)-d,
        sdTwistedStrip(p+vec3(0,0,e),R,w,h,twist)-d
    ));
}

vec4 hafizePortrait(vec2 p) {
    float aspect=uRes.x/uRes.y; vec2 uv=p*vec2(aspect,1.0);
    vec3 bgDark=vec3(0.122,0.122,0.133), bgLight=vec3(0.969,0.957,0.933);
    vec3 gold=vec3(0.784,0.663,0.431), brightGold=vec3(0.910,0.831,0.659);
    vec3 earth=vec3(0.478,0.427,0.329), darkEarth=vec3(0.227,0.208,0.188), warmEarth=vec3(0.55,0.45,0.30);
    vec3 bg=mix(bgDark,bgLight,uLight); vec3 col=bg; float alpha=0.0;

    float idleW=1.0-uListen-uThink-uSpeak;
    float rotAngle=uFlow*mix(0.1,0.8,uThink)*6.28318;
    float breath=sin(uTime*0.314)*0.02*(1.0+uListen*0.5);
    float R=0.45+breath;
    float w=0.18*(1.0+uListen*0.08);
    float h=0.025;
    float edgeVib=uListen*uEnergy*0.01;

    float pulse=0.0, speakPhase=0.0;
    if(uSpeak>0.01) {
        speakPhase=uTime*45.0;
        float env=smoothstep(0.0,1.0,uVoice)*smoothstep(1.0,0.85,uVoice);
        pulse=env*0.08*pow(uVoice,1.5);
        R+=pulse; w+=pulse*0.5;
    }

    vec3 ro=vec3(uv.x,uv.y,1.5); vec3 rd=vec3(0.0,0.0,-1.0);
    ro=rotY(ro,-rotAngle); rd=rotY(rd,-rotAngle);

    float t=0.0; bool hit=false; vec3 pos, nor; float face=0.0, depth=0.0, widthCoord=0.0;
    for(int i=0;i<16;i++) {
        vec3 p3=ro+rd*t; float ang=atan(p3.z,p3.x);
        float wVib=w+noise(vec2(ang*8.0,uTime*2.0))*edgeVib;
        float d=sdTwistedStrip(p3,R,wVib,h,0.0);
        if(d<0.001) { hit=true; pos=p3; break; }
        t+=max(d,0.002); if(t>3.0) break;
    }

    if(hit) {
        nor=getNormal(pos,R,w,h,0.0);
        float ang=atan(pos.z,pos.x);
        vec2 q=vec2(length(pos.xz)-R, pos.y);
        q=rot2(q, ang*0.5);
        face=sign(q.y); depth=abs(q.y)/h; widthCoord=q.x/w;

        vec3 V=-rd; vec3 L=normalize(vec3(0.5,1.0,0.3));
        float NdotL=max(dot(nor,L),0.0); float NdotV=max(dot(nor,V),0.0);
        float rim=pow(1.0-NdotV,2.5); float ao=1.0-depth*0.5;

        vec3 albedo, specCol=vec3(0.0); float rough=0.7; vec3 emissive=vec3(0.0);
        float listenBoost=uListen*0.8; float thinkBoost=uThink*0.8; float speakBoost=uSpeak*uVoice;

        if(face>0.0) { // Outer: Listening
            albedo=mix(uLight>0.5?darkEarth:gold, brightGold, listenBoost);
            rough=mix(0.8,0.4,listenBoost);
            specCol=mix(vec3(0.02),vec3(0.4),listenBoost);
            emissive+=vec3(0.02)*listenBoost;
        } else { // Inner: Thinking/Speaking
            albedo=mix(uLight>0.5?darkEarth:warmEarth, gold, thinkBoost+speakBoost);
            rough=mix(0.5,0.3,thinkBoost);
            specCol=mix(vec3(0.04),vec3(0.6),thinkBoost);
            emissive+=gold*0.15*thinkBoost;
            emissive+=brightGold*0.4*speakBoost;
        }

        float speakPulse=speakBoost*(1.0-abs(sin(speakPhase)));
        vec3 lightCol=mix(gold, brightGold, speakPulse);
        vec3 diff=albedo*NdotL*0.7*ao;
        vec3 spec=specCol*pow(max(dot(reflect(-L,nor),V),0.0), 32.0/rough)*NdotL;
        vec3 rimCol=lightCol*rim*(0.3+0.7*listenBoost+0.5*speakBoost);
        col=diff+spec+rimCol+emissive;

        if(face<0.0 && uThink>0.01) {
            float spiral=ang*5.0-length(pos.xz)*15.0+uTime*2.0;
            for(int i=0;i<3;i++) {
                float nz=fbm(vec2(ang*10.0+float(i)*2.0, uTime*0.1),3);
                float line=smoothstep(0.02,0.0,abs(sin(spiral+float(i)*2.094+nz*3.0))-uPx*3.0);
                col+=gold*0.1*line*uThink*(1.0-depth);
                alpha=max(alpha,line*uThink*0.4);
            }
        }

        alpha=smoothstep(uPx*2.0,-uPx*2.0,sdTwistedStrip(pos,R,w,h,0.0));
    }

    col=vec3(1.0)-exp(-col*1.3);
    col=mix(bg,col,alpha);
    return vec4(col,alpha);
}
